    gap: 8,
  },
  name: {
    fontSize: 15,
    fontWeight: '600' as const,
    color: Colors.text,
    flexShrink: 1,
  },
  summitBadge: {
    borderWidth: 1.5,
    borderColor: '#C0392B',
